export function ActivityHeatmap({descriptor,label,formatDay,view='grid',layoutStyle}:ActivityHeatmapProps){const {days,columns}=resolveActivityHeatmap(descriptor);return <div role="region" aria-label={label} tabIndex={view==='grid'?0:undefined} style={{...layoutStyle,overflowX:'auto'}}><ul aria-label={label} style={view==='grid'?{display:'grid',gridTemplateRows:'repeat(7, 1rem)',gridTemplateColumns:`repeat(${columns}, 1rem)`,gap:'var(--hjm-space-xxs)',listStyle:'none',padding:0,margin:0}:undefined}>{days.map(day=><li key={day.date} aria-label={view==='grid'?formatDay(day.date,day.value):undefined} title={formatDay(day.date,day.value)} style={view==='grid'?{gridRow:day.row+1,gridColumn:day.column+1,borderRadius:'calc(var(--hjm-radius-sm) / 4)',background:day.level===0?'var(--hjm-color-surface-alt)':`color-mix(in srgb, var(--hjm-color-content-brand) ${25*day.level}%, var(--hjm-color-surface-alt))`,outline:day.value===null?'1px dashed var(--hjm-color-border)':undefined}:undefined}>{view==='list'?formatDay(day.date,day.value):null}</li>)}</ul></div>;}
